parsed_args.contents:
import base64
from itertools import cycle
from collections import Counter
import string

def score_english(text):
    text = text.lower()
    common = b" etaoinshrdlucmfwypvbgkqjxz"
    return sum([c in common for c in text])

def single_byte_xor(bytez):
    scores = []
    for k in range(256):
        pt = bytes([b ^ k for b in bytez])
        score = score_english(pt)
        scores.append((score, k, pt))
    return max(scores)

def break_repeating_key_xor(ciphertext, keylen):
    key = bytearray()
    for i in range(keylen):
        block = ciphertext[i::keylen]
        _, k, _ = single_byte_xor(block)
        key.append(k)
    return key

def decrypt(ciphertext, key):
    return bytes([c ^ k for c, k in zip(ciphertext, cycle(key))])

with open("/home/ctfplayer/ctf_files/ciphertext.txt", "r") as f:
    ct_b64 = f.read().strip()

ct = base64.b64decode(ct_b64)

for keylen in [16, 8, 2, 11, 4]:
    key = break_repeating_key_xor(ct, keylen)
    pt = decrypt(ct, key)
    print(f"\nKeylen: {keylen}  Key: {list(key)}  (as ascii: {''.join(chr(b) if 32 <= b <= 126 else '.' for b in key)})")
    snip = pt[:300].replace(b'\n', b' ')
    try:
        text = snip.decode('utf-8', errors='replace')
    except:
        text = str(snip)
    print(text)

